// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(address actor, uint64 t, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(t <= block.timestamp); // a past-or-current timestamp is always admissible
        amount = bound(amount, 1, 10 ether);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(t);
        (, uint256 bal) = c.Acc(actor);
        if (bal >= amount) {
            (uint256 unlockTime,) = c.Acc(actor);
            assertTrue(unlockTime >= block.timestamp);
        }
    }
}
